<?php
require_once __DIR__.'/../includes/auth.php';requireAdmin();require_once __DIR__.'/../includes/mailer.php';
$months=['monthly'=>1,'quarterly'=>3,'yearly'=>12];
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$id=(int)($_POST['request_id']??0);$action=$_POST['action']??'';$reason=trim((string)($_POST['reason']??''));$q=$pdo->prepare("SELECT r.*,u.name,u.email FROM subscription_requests r JOIN users u ON u.id=r.user_id WHERE r.id=? AND r.status='pending'");$q->execute([$id]);$r=$q->fetch();if($r){if($action==='approve'){$start=new DateTimeImmutable('today');$end=$start->modify('+'.$months[$r['plan']].' months');$pdo->beginTransaction();$pdo->prepare("UPDATE subscription_requests SET status='approved',admin_reason=?,reviewed_at=NOW(),reviewed_by=?,starts_on=?,expires_on=? WHERE id=?")->execute([$reason?:null,$_SESSION['user_id'],$start->format('Y-m-d'),$end->format('Y-m-d'),$id]);$pdo->prepare("UPDATE users SET subscription_plan=?,subscription_status='active',subscription_expires_at=? WHERE id=?")->execute([$r['plan'],$end->format('Y-m-d'),$r['user_id']]);$pdo->commit();$msg='Your '.$r['plan'].' Premium subscription has been approved. Access starts '.$start->format('F j, Y').' and expires '.$end->format('F j, Y').'.';fittrackNotify($pdo,(int)$r['user_id'],'Subscription approved',$msg,'Your FitTrack subscription is approved');}elseif($action==='reject'){$pdo->prepare("UPDATE subscription_requests SET status='rejected',admin_reason=?,reviewed_at=NOW(),reviewed_by=? WHERE id=?")->execute([$reason?:'Please contact FitTrack support for details.',$_SESSION['user_id'],$id]);fittrackNotify($pdo,(int)$r['user_id'],'Subscription request not approved',$reason?:'Your subscription request was not approved. Please contact FitTrack support.','Update on your FitTrack subscription request');}flash('Subscription request updated.');}redirect('requests.php');}
$rows=$pdo->query('SELECT r.*,u.name,u.email,u.fitness_level FROM subscription_requests r JOIN users u ON u.id=r.user_id ORDER BY r.requested_at DESC')->fetchAll();$pending=(int)$pdo->query("SELECT COUNT(*) FROM subscription_requests WHERE status='pending'")->fetchColumn();$pageTitle='Subscription requests';require __DIR__.'/../includes/header.php';?>
<section class="page-heading"><div><p class="eyebrow">MEMBERSHIP CONTROL</p><h1>Subscription requests <span class="badge"><?=$pending?> pending</span></h1><p>Review payment proofs and approve or reject membership requests.</p></div></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Member</th><th>Plan</th><th>Payment proof</th><th>Requested</th><th>Status</th><th>Decision</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><br><?=e($r['email'])?><br><small><?=e(ucfirst($r['fitness_level']??''))?></small></td><td><?=e(ucfirst($r['plan']))?><br><?=e($r['payment_reference']??'')?></td><td><?php if($r['proof_file']):?><a target="_blank" rel="noopener" href="payment-proof.php?id=<?=(int)$r['id']?>">View proof</a><?php else:?>—<?php endif;?></td><td><?=e($r['requested_at'])?></td><td><?=e(ucfirst($r['status']))?></td><td><?php if($r['status']==='pending'):?><form method="post" class="admin-decision"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="request_id" value="<?=(int)$r['id']?>"><input name="reason" placeholder="Optional admin note"><button class="button btn-small" name="action" value="approve">Approve</button><button class="button danger btn-small" name="action" value="reject">Reject</button></form><?php else:?><?=e($r['admin_reason']??'—')?><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php';?>
